BEGIN;
INSERT INTO auth.users(id,email) VALUES
('dc262626-0001-4000-8000-000000000001','xroga-migration-owner@invalid.example'),
('dc272727-0002-4000-8000-000000000002','xroga-migration-foreign@invalid.example');
SET LOCAL ROLE service_role;
DO $proof$
DECLARE
 o uuid := 'dc262626-0001-4000-8000-000000000001';
 f uuid := 'dc272727-0002-4000-8000-000000000002';
 d uuid := 'dc262626-0010-4000-8000-000000000010';
 r uuid := 'dc262626-0020-4000-8000-000000000020';
 t uuid := 'dc262626-0030-4000-8000-000000000030';
 w uuid := 'dc262626-0040-4000-8000-000000000040';
 g uuid := 'dc262626-0050-4000-8000-000000000050';
 s text := repeat('b',40); result jsonb; rejected boolean := false;
BEGIN
 result := public.enqueue_google_canonical_run(d,r,o,NULL,'{"prompt":"synthetic hosted migration proof"}',s);
 ASSERT result->>'deliveryId'=d::text,'Hosted enqueue failed';
 BEGIN
  PERFORM public.enqueue_google_canonical_run(d,r,f,NULL,'{"prompt":"synthetic hosted migration proof"}',s);
 EXCEPTION WHEN OTHERS THEN
  IF SQLERRM='DELIVERY_NOT_FOUND' THEN rejected:=true; ELSE RAISE; END IF;
 END;
 ASSERT rejected,'Foreign owner was not denied';
 result := public.reserve_google_canonical_launch(d,s,t);
 ASSERT result->>'state'='reserved','Hosted launch reservation failed';
 result := public.claim_google_canonical_run(d,s,w::text,g);
 ASSERT result->>'userId'=o::text,'Hosted worker claim owner mismatch';
 ASSERT public.claim_google_canonical_run(d,s,'dc262626-0041-4000-8000-000000000041',g) IS NULL,'Duplicate worker was admitted';
 PERFORM public.cancel_swarm_run_owned(r,o);
 ASSERT (public.reserve_google_canonical_launch(d,s,t)->>'state')='acknowledged','Cancelled run dispatch reopened';
 ASSERT public.claim_google_canonical_run(d,s,w::text,g) IS NULL,'Cancelled run issued a claim';
END
$proof$;
RESET ROLE;
SELECT jsonb_build_object('status','PASS_HOSTED_SYNTHETIC_ROLLBACK_SCHEMA_PROOF',
 'ownerEnqueue',true,'foreignOwnerDenied',true,'claimOwnerBound',true,
 'duplicateClaimDenied',true,'originalCancellationDeniedRedispatch',true,
 'browserTableDenied',NOT has_table_privilege('authenticated','public.google_canonical_deliveries','SELECT'),
 'anonymousClaimDenied',NOT has_function_privilege('anon','public.claim_google_canonical_run(uuid,text,text,uuid)','EXECUTE'),
 'productionChanged',false,'rollbackRequired',true) as evidence;
ROLLBACK;
